head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
	var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
	var r = d(id); if (r) return r;
	var s = dd(P + id); r = d(s); if (r) return r;
	var g = s.indexOf('G_');
	if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
	return d(s.replace(P, ''));
};

scwin.gridView1_onrightbuttonclick = function(row, col) {
	WebSquare.logger.printLog("gridView1_onrightbuttonclick call");
};

scwin.fireOver = function(node) {
	var evt = document.createEvent('MouseEvents');
	evt.initEvent('mouseover', true, false);
	node.dispatchEvent(evt);
};

scwin.rightClick = function(id) {
	var node = scwin.__getDom($p.id + id);
	var evt = document.createEvent('MouseEvents');
	evt.initEvent('contextmenu', true, false);
	node.dispatchEvent(evt);
};

scwin.mouseOverBehaviour = function(id) {
	scwin.fireOver(scwin.__getDom($p.id + id));
};

scwin.checkVal = function(id) {
	return scwin.__getDom($p.id + id) ? true : false;
};

scwin.checkLog = function(text) {
	return WebSquare.logger.getLog().indexOf(text) >= 0;
};

scwin.onpageload = function() {
	dataList1.setJSON([
		{"col1": "aaaa1", "col2": "bbbb1", "col3": "cccc1", "col4": "dddd1"},
		{"col1": "aaaa2", "col2": "bbbb2", "col3": "cccc2", "col4": "dddd2"},
		{"col1": "aaaa3", "col2": "bbbb3", "col3": "cccc3", "col4": "dddd3"},
		{"col1": "aaaa4", "col2": "bbbb4", "col3": "cccc4", "col4": "dddd4"}
	]);
};
